IF DB_ID('B2B_Project_DB') IS NULL
    CREATE DATABASE [B2B_Project_DB];
GO

USE [B2B_Project_DB];
GO

-- Tabloları temizle (yeniden çalıştırılabilirlik için)
IF OBJECT_ID('OrderDetails') IS NOT NULL DROP TABLE [OrderDetails];
IF OBJECT_ID('RecurringOrders') IS NOT NULL DROP TABLE [RecurringOrders];
IF OBJECT_ID('Orders') IS NOT NULL DROP TABLE [Orders];
IF OBJECT_ID('Users') IS NOT NULL DROP TABLE [Users];
IF OBJECT_ID('Products') IS NOT NULL DROP TABLE [Products];
GO

CREATE TABLE [Products] (
  [Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY,
  [Barcode] nvarchar(50) NOT NULL,
  [Name] nvarchar(100) NOT NULL,
  [AvailableStock] int NOT NULL,
  [CostPrice] decimal(18,2) NOT NULL,
  [WholeSalePrice] decimal(18,2) NOT NULL,
  [Currency] nvarchar(10) NOT NULL,
  [MinOrderQuantity] int NOT NULL,
  [IsActive] bit NOT NULL,
  [ImageBase64] nvarchar(max) NULL
);

CREATE TABLE [Users] (
  [Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY,
  [Username] nvarchar(50) NOT NULL,
  [Password] nvarchar(255) NOT NULL,
  [CompanyName] nvarchar(100) NOT NULL,
  [Role] nvarchar(20) NOT NULL,
  [CreditLimit] decimal(18,2) NOT NULL,
  [CurrentBalance] decimal(18,2) NOT NULL,
  [IsActive] bit NOT NULL,
  [Email] nvarchar(100) NULL,
  [Phone] nvarchar(20) NULL,
  [Address] nvarchar(500) NULL,
  [TaxOffice] nvarchar(100) NULL,
  [PasswordResetRequested] bit NULL
);

CREATE TABLE [Orders] (
  [Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY,
  [UserId] int NOT NULL,
  [OrderDate] datetime NOT NULL,
  [TotalAmount] decimal(18,2) NOT NULL,
  [Status] nvarchar(20) NOT NULL,
  [IsAutomated] bit NOT NULL,
  [OrderNumber] nvarchar(50) NOT NULL
);

CREATE TABLE [OrderDetails] (
  [Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY,
  [OrderId] int NOT NULL,
  [ProductId] int NOT NULL,
  [Quantity] int NOT NULL,
  [UnitPrice] decimal(18,2) NOT NULL
);

CREATE TABLE [RecurringOrders] (
  [Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY,
  [UserId] int NOT NULL,
  [ProductId] int NOT NULL,
  [Quantity] int NOT NULL,
  [PeriodInWeeks] int NOT NULL,
  [NextRunDate] datetime NOT NULL,
  [IsActive] bit NOT NULL
);

SET IDENTITY_INSERT [Products] ON;
SET IDENTITY_INSERT [Products] OFF;
SET IDENTITY_INSERT [Users] ON;

SET IDENTITY_INSERT [Users] OFF;
SET IDENTITY_INSERT [Orders] ON;

SET IDENTITY_INSERT [Orders] OFF;
SET IDENTITY_INSERT [OrderDetails] ON;

SET IDENTITY_INSERT [OrderDetails] OFF;
SET IDENTITY_INSERT [RecurringOrders] ON;

SET IDENTITY_INSERT [RecurringOrders] OFF;
GO

